482	//    no record; fixing it then creates exactly one draft.
483	// ---------------------------------------------------------------------------
484	test('新建态保存被服务端拒绝：保留新建状态与全部输入，修正后只创建一篇', async (browser) => {
485	  const ctx = await freshContext(browser);
