499	    assert.ok(s.statusText.includes('保存失败'));
500	    assert.equal(s.saveBtnText, '保存草稿');
501	    assert.equal(s.bannerHidden, true);
502	    assert.equal(s.formEditing, false);
503	    assert.equal(s.cancelHidden, true);
