759	function readBody(req: IncomingMessage): Promise<string> {
760	  return new Promise((resolve, reject) => {
761	    const chunks: Buffer[] = [];
762	    let size = 0;
763	    let tooLarge = false;
764	    let settled = false;
765	    // A declared Content-Length already tells us the request will exceed the
766	    // limit, but we must still consume the whole request before responding;
767	    // skip buffering from the start to bound memory use while draining.
768	    const declaredLength = Number(req.headers['content-length']);
769	    if (Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES) {
770	      tooLarge = true;
771	    }
772	    req.on('data', (chunk: unknown) => {
773	      if (settled) return;
774	      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk));
775	      if (tooLarge) return; // draining the remainder; nothing left to buffer
776	      size += buf.length;
777	      if (size > MAX_BODY_BYTES) {
778	        // Keep reading (and discarding) the rest of the request instead of
779	        // calling req.destroy(): destroying the socket resets the connection
780	        // while the client is still sending, so it would never receive the
781	        // 400 response (only a network failure). The full request is drained,
782	        // then the rejection below produces a complete, readable response.
783	        tooLarge = true;
784	        chunks.length = 0;
785	        return;
786	      }
787	      chunks.push(buf);
788	    });
789	    req.on('end', () => {
790	      if (settled) return;
791	      settled = true;
792	      if (tooLarge) {
793	        reject(new HttpError(400, `request body exceeds the allowed size of ${MAX_BODY_BYTES} bytes`));
794	        return;
795	      }
796	      resolve(Buffer.concat(chunks).toString('utf8'));
797	    });
798	    req.on('error', (error: Error) => {
799	      if (settled) return;
800	      settled = true;
801	      reject(new HttpError(400, `could not read request body: ${error.message}`));
802	    });
803	    req.on('aborted', () => {
804	      if (settled) return;
805	      settled = true;
806	      reject(new HttpError(400, 'request body was not fully received'));
807	    });
808	  });
809	}
810	
811	function parseJsonObject(text: string): Record<string, unknown> {
812	  let payload: unknown;
813	  try {
814	    payload = JSON.parse(text);
815	  } catch (error) {
816	    throw new HttpError(400, `invalid JSON: ${(error as Error).message}`);
817	  }
818	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
819	    throw new HttpError(400, 'request body must be a JSON object');
820	  }
821	  return payload as Record<string, unknown>;
822	}
823	
824	function validateDraftInput(data: Record<string, unknown>): DraftInput {
825	  if (typeof data.title !== 'string') {
826	    throw new HttpError(400, 'title must be a string');
827	  }
828	  const title = data.title.trim();
829	  if (title.length === 0) {
830	    throw new HttpError(400, 'title must not be empty or only whitespace');
831	  }
832	  let summary = '';
833	  if (Object.prototype.hasOwnProperty.call(data, 'summary')) {
834	    if (typeof data.summary !== 'string') throw new HttpError(400, 'summary must be a string when provided');
835	    summary = data.summary;
836	  }
837	  if (typeof data.body !== 'string') {
838	    throw new HttpError(400, 'body must be a string');
839	  }
840	  return { title, summary, body: data.body };
841	}
842	
843	// Updates carry the version the editor loaded; stale versions are rejected.
844	// As with creation, summary may be omitted (saved as empty string) but a
845	// present non-string summary is a 400.
846	function validateUpdateInput(data: Record<string, unknown>): DraftInput & { version: number } {
847	  const fields = validateDraftInput(data);
848	  if (typeof data.version !== 'number' || !Number.isInteger(data.version) || data.version < 0) {
849	    throw new HttpError(400, 'version must be a non-negative integer');
850	  }
851	  return { ...fields, version: data.version };
852	}
