854	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
855	  let route: string;
856	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; }
857	  catch { respond(res, 400, { error: 'invalid request path' }); return; }
858	
859	  // /api/articles/:id (match the raw path first; decode only the captured id)
860	  const itemMatch = /^\/api\/articles\/([^/]+)$/.exec(route);
861	  let itemId: string | null = null;
862	  if (itemMatch) {
863	    try { itemId = decodeURIComponent(itemMatch[1]); }
864	    catch { respond(res, 400, { error: 'invalid article id encoding' }); return; }
865	  }
866	
867	  if (!['/', '/health', '/api/articles'].includes(route) && !itemMatch) {
868	    respond(res, 404, { error: 'not found' });
869	    return;
870	  }
871	
872	  if (route === '/') {
873	    if (req.method === 'GET') { respond(res, 200, PAGE, true); return; }
874	    methodNotAllowed(res, 'GET');
875	    return;
876	  }
877	  if (route === '/health') {
878	    if (req.method === 'GET') { respond(res, 200, { status: 'ok', product: PRODUCT }); return; }
879	    methodNotAllowed(res, 'GET');
880	    return;
881	  }
882	
883	  if (itemMatch && itemId !== null) {
884	    const id = itemId;
885	    if (req.method === 'GET') {
886	      const articles = readArticles();
887	      const article = articles.find((a) => a.id === id);
888	      if (!article) throw new HttpError(404, 'article not found');
889	      respond(res, 200, { article });
890	      return;
891	    }
892	    if (req.method === 'PUT') {
893	      const text = await readBody(req);
894	      const data = parseJsonObject(text);
895	      const fields = validateUpdateInput(data);
896	      const result = await enqueueWrite((): { status: number; article: Article } => {
897	        const records = readArticles();
898	        const index = records.findIndex((a) => a.id === id);
899	        if (index === -1) {
900	          throw new HttpError(404, 'article not found');
901	        }
902	        const current = records[index];
903	        if (fields.version !== current.version) {
904	          // 409 carries the currently saved article for side-by-side comparison.
905	          const conflict = new HttpError(409, 'a newer version of this article has been saved');
906	          (conflict as HttpError & { article?: Article }).article = current;
907	          throw conflict;
908	        }
909	        const updated: Article = {
910	          id: current.id,
911	          title: fields.title,
912	          summary: fields.summary,
913	          body: fields.body,
914	          status: current.status,
915	          createdAt: current.createdAt,
916	          version: current.version + 1,
917	        };
918	        records[index] = updated;
919	        writeArticles(records);
920	        return { status: 200, article: updated };
921	      });
922	      respond(res, result.status, { article: result.article });
